def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        safe_bid = min(budget, DAILY_SALARY * 0.35)
        if hp <= 2 or no_water_days >= 2:
            safe_bid = min(budget, DAILY_SALARY * 0.8)
        return max(0, safe_bid)

    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0
    total_alive = len(alive_opponents)

    for opp in alive_opponents:
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_opponents += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            urgent_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0))

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    my_urgent = hp <= 2 or no_water_days >= 2
    somewhat_urgent = hp <= 4 or no_water_days >= 1

    supply_ratio = supply / float(WATER_REQ)
    contested = supply_ratio < (total_alive + 1)
    very_tight = supply_ratio < max(1.2, (total_alive + 1) * 0.7)

    if my_urgent:
        base = DAILY_SALARY * 0.92
        if highest_prev > 0:
            base = max(base, highest_prev + 2)
        if very_tight:
            base = max(base, DAILY_SALARY * 0.98)
        return max(0, min(budget, base))

    if very_tight:
        base = DAILY_SALARY * 0.72
        if highest_prev > 0:
            base = max(base, highest_prev + 1.5)
        if urgent_opponents >= total_alive / 2.0:
            base += 3
        return max(0, min(budget, base))

    if contested:
        base = DAILY_SALARY * 0.56
        if highest_prev >= DAILY_SALARY * 0.8:
            base = DAILY_SALARY * 0.42 if hp > 4 else DAILY_SALARY * 0.86
        elif highest_prev > 0:
            base = max(base, avg_prev + 1)
        if somewhat_urgent:
            base = max(base, DAILY_SALARY * 0.68)
        return max(0, min(budget, base))

    base = DAILY_SALARY * 0.28
    if highest_prev > 0 and highest_prev < DAILY_SALARY * 0.4:
        base = max(base, highest_prev * 0.9)
    if somewhat_urgent:
        base = max(base, DAILY_SALARY * 0.45)
    if rich_opponents == total_alive and avg_prev > DAILY_SALARY * 0.6:
        base = DAILY_SALARY * 0.22

    return max(0, min(budget, base))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    budget = float(my_status.get('budget', 0.0))
    hp = float(my_status.get('hp', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # If we can’t read opponent behavior, choose a robust bid.
    # Baseline depends on supply: lower supply => higher bid to secure allocation.
    if supply <= float(MIN_SUPPLY):
        base_frac = 0.62
    elif supply >= float(MAX_SUPPLY):
        base_frac = 0.48
    else:
        # Linear interpolation between MIN_SUPPLY and MAX_SUPPLY
        t = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
        base_frac = 0.62 - 0.14 * t

    # React to our own risk.
    risk_boost = 0.0
    if hp <= 2.0:
        risk_boost = 0.35
    elif hp <= 3.0:
        risk_boost = 0.20

    if no_water_days >= 2:
        risk_boost = max(risk_boost, 0.25)
    elif no_water_days >= 1:
        risk_boost = max(risk_boost, 0.12)

    # Also, if any opponent yesterday bid was extremely high, slightly increase.
    # (We only look at previous_trace from yesterday per rules.)
    extreme_prev = False
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        prev_bid = prev.get('bid', None)
        if prev_bid is not None:
            try:
                if float(prev_bid) >= 0.85 * DAILY_SALARY:
                    extreme_prev = True
                    break
            except Exception:
                pass

    if extreme_prev:
        base_frac = max(base_frac, 0.70)

    target = DAILY_SALARY * (base_frac + risk_boost)

    # Convert target to a bid that is always feasible and conservative.
    bid = min(budget, target)

    # Ensure not bidding trivially low; still respect budget.
    min_bid = min(budget, DAILY_SALARY * 0.25)
    if bid < min_bid:
        bid = min_bid

    # If we are in late episode days, be more aggressive.
    if day >= 8:
        bid = min(budget, max(bid, DAILY_SALARY * 0.65))

    # Final clamp to non-negative.
    if bid < 0.0:
        bid = 0.0
    return bid

